export function evolutionFor(game,plant){const id=game.selectedEvolutions?.[typeof plant==='string'?plant:plant.id];return EVOLUTIONS.find(e=>e.id===id)||null}
export function evolutionChoices(game,rng=Math.random,count=3){let used=[...new Set(game.plants.filter(p=>p.hp>0).map(p=>p.id))].filter(id=>!game.selectedEvolutions[id]);if(!used.length)used=['peashooter','sunflower','wallNut'].filter(id=>!game.selectedEvolutions[id]);let pool=EVOLUTIONS.filter(e=>used.includes(e.plant)),out=[];while(pool.length&&out.length<count){const i=Math.floor(rng()*pool.length),e=pool.splice(i,1)[0];out.push(e);pool=pool.filter(x=>x.plant!==e.plant)}if(out.length<count)for(const e of EVOLUTIONS)if(!game.selectedEvolutions[e.plant]&&!out.some(x=>x.id===e.id)){out.push(e);if(out.length===count)break}return out}
